using System.Windows;
using System.Windows.Controls;
using MizanDesktop.Services;
namespace MizanDesktop.Views;
public sealed class CostLayersView:UserControl{public CostLayersView(AppRepository repo){FlowDirection=FlowDirection.RightToLeft;var root=new DockPanel{Margin=new Thickness(15)};var t=new TextBlock{Text="طبقات تكلفة المخزون (FIFO)",FontSize=24,FontWeight=FontWeights.Bold};DockPanel.SetDock(t,Dock.Top);root.Children.Add(t);var info=new TextBlock{Text="يتم استهلاك أقدم طبقات التكلفة عند البيع والمرتجع.",Margin=new Thickness(0,5,0,12)};DockPanel.SetDock(info,Dock.Top);root.Children.Add(info);var g=new DataGrid{AutoGenerateColumns=false,IsReadOnly=true};g.Columns.Add(new DataGridTextColumn{Header="الصنف",Binding=new System.Windows.Data.Binding("Product")});g.Columns.Add(new DataGridTextColumn{Header="رقم المرجع",Binding=new System.Windows.Data.Binding("Number")});g.Columns.Add(new DataGridTextColumn{Header="الكمية",Binding=new System.Windows.Data.Binding("Quantity")});g.Columns.Add(new DataGridTextColumn{Header="المتبقي",Binding=new System.Windows.Data.Binding("Remaining")});g.Columns.Add(new DataGridTextColumn{Header="تكلفة الوحدة",Binding=new System.Windows.Data.Binding("UnitCost")});g.Columns.Add(new DataGridTextColumn{Header="العملة",Binding=new System.Windows.Data.Binding("Currency")});g.Columns.Add(new DataGridTextColumn{Header="التاريخ",Binding=new System.Windows.Data.Binding("Date")});g.ItemsSource=repo.CostLayersReport();root.Children.Add(g);Content=root;}}
